/** Subset of AgentApprovalStatus valid as a resolution input (excludes PENDING). */
export type AgentApprovalDecision =
  | 'APPROVED'
  | 'DENIED';

export type AgentApprovalStatus =
  | 'APPROVED'
  | 'DENIED'
  | 'PENDING';

export type AgentMode =
  | 'LIVE'
  | 'SHADOW';

/**
 * When Sidekick is allowed to use a tool:
 * - NOT_REQUIRED: Sidekick runs the tool directly.
 * - APPROVAL_REQUIRED: Sidekick must request human approval before running it.
 * - DISABLED: the tool is listed to Sidekick but every call is rejected.
 */
export type AgentSandboxToolMode =
  | 'APPROVAL_REQUIRED'
  | 'DISABLED'
  | 'NOT_REQUIRED';

/**
 * The resolved approval policy for one Sidekick tool: its effective mode plus the
 * factory default it derives from.
 */
export type AgentSandboxToolPolicy = {
  /** One-line description shown as the row subtitle. */
  description: Scalars['String']['output'];
  /** Human-readable tool name shown as the row label. */
  displayName: Scalars['String']['output'];
  /** The mode this tool uses when the workspace has set no override. */
  factoryDefault: AgentSandboxToolMode;
  /** True when the effective mode comes from a workspace override rather than the default. */
  isOverride: Scalars['Boolean']['output'];
  /** Effective mode after merging the workspace override over the factory default. */
  mode: AgentSandboxToolMode;
  /** Op id within the service, e.g. "thread.note". */
  op: Scalars['String']['output'];
  /** Registry service name, e.g. "plain" or "slack". */
  service: Scalars['String']['output'];
};

export type AgentSessionDelta = {
  agentSessionId: Scalars['ID']['output'];
  /** An incremental text chunk from the agent's current response. Append successive chunks to reconstruct the full message. */
  text: Scalars['String']['output'];
};

