/** A single piece of feedback a teammate submitted on a Plain AI feature result. */
export type AiFeedback = {
  createdAt: DateTime;
  /** The user or machine user who submitted this feedback. */
  createdBy: InternalActor;
  /** Feature-specific context for the feedback, including the sentiment, the optional free-text comment, and the ID of whatever the feedback was left on. */
  details: AiFeatureFeedbackDetails;
  feature: AiFeedbackFeature;
  id: Scalars['ID']['output'];
  updatedAt: DateTime;
  /** The user or machine user who last modified this feedback. */
  updatedBy: InternalActor;
};

export type AiFeedbackConnection = {
  edges: Array<AiFeedbackEdge>;
  pageInfo: PageInfo;
  totalCount: Scalars['Int']['output'];
};

export type AiFeedbackEdge = {
  cursor: Scalars['String']['output'];
  node: AiFeedback;
};

/** The Plain AI feature a piece of feedback relates to. */
export type AiFeedbackFeature =
  /** A reply drafted or sent by Ari, Plain's AI agent. */
  | 'AI_AGENT'
  /** A knowledge gap detected from questions your customers are not finding answers to. */
  | 'KNOWLEDGE_GAP'
  /** An AI-generated summary of what has happened so far on a thread. */
  | 'THREAD_CATCHUP'
  /** A cluster of related threads surfaced by Plain's AI. */
  | 'THREAD_CLUSTERS'
  /** An AI tone rule governing how Plain's AI writes. */
  | 'TONE_RULE';

export type AiFeedbackFilter = {
  /** Only return feedback submitted within this time window. */
  createdAt?: InputMaybe<DatetimeFilter>;
  /** Only return feedback on these AI features. */
  features?: InputMaybe<Array<AiFeedbackFeature>>;
  /** Only return feedback with these sentiments. Feedback submitted before sentiment was captured has no sentiment and is excluded by this filter. */
  sentiments?: InputMaybe<Array<AiFeedbackSentiment>>;
};

export type AiFeedbackSentiment =
  | 'NEGATIVE'
  | 'NEUTRAL'
  | 'POSITIVE';

