/** An SLA that tracks the time from thread creation until the thread is first marked Done. Reopening a thread does not start a new tracker. */
export type FirstResolutionTimeServiceLevelAgreement = ServiceLevelAgreement & {
  breachActions: Array<BreachAction>;
  /** The business hours schedules this SLA is tracked against. Empty if the SLA is tracked 24/7. */
  businessHoursSchedules: Array<BusinessHoursSchedule>;
  createdAt: DateTime;
  createdBy: InternalActor;
  /** This SLA will breach if the thread is not first marked Done within this many minutes. */
  firstResolutionTimeMinutes: Scalars['Int']['output'];
  id: Scalars['ID']['output'];
  /** The thread status details that pause this first-resolution-time clock. Empty means the clock never pauses. Defaults to waiting for the customer. */
  pauseOnStatusDetailTypes: Array<ServiceLevelAgreementPauseStatusDetailType>;
  threadLabelTypeIdFilter?: Maybe<ServiceLevelAgreementThreadLabelTypeIdFilter>;
  threadPriorityFilter: Array<Scalars['Int']['output']>;
  updatedAt: DateTime;
  updatedBy: InternalActor;
  useBusinessHoursOnly: Scalars['Boolean']['output'];
};

/** An SLA that tracks the time from thread creation until a teammate sends the first reply. */
export type FirstResponseTimeServiceLevelAgreement = ServiceLevelAgreement & {
  breachActions: Array<BreachAction>;
  /** The business hours schedules this SLA is tracked against. Empty if the SLA is tracked 24/7. */
  businessHoursSchedules: Array<BusinessHoursSchedule>;
  createdAt: DateTime;
  createdBy: InternalActor;
  /** This SLA will breach if it does not receive a first response within this many minutes. */
  firstResponseTimeMinutes: Scalars['Int']['output'];
  id: Scalars['ID']['output'];
  threadLabelTypeIdFilter?: Maybe<ServiceLevelAgreementThreadLabelTypeIdFilter>;
  threadPriorityFilter: Array<Scalars['Int']['output']>;
  updatedAt: DateTime;
  updatedBy: InternalActor;
  /** @deprecated Use businessHoursSchedules to see which business hours are linked to this SLA. */
  useBusinessHoursOnly: Scalars['Boolean']['output'];
};

