export type KnowledgeSourceSearchResultType =
  /** A result from a published help center article. */
  | 'HELP_CENTER_ARTICLE'
  /** A result from a manually indexed document or sitemap-crawled page. */
  | 'INDEXED_DOCUMENT';

export type KnowledgeSourceSitemap = {
  createdAt: DateTime;
  createdBy: InternalActor;
  id: Scalars['ID']['output'];
  /** Counts of URLs crawled from this sitemap, broken down by their individual indexing status. */
  indexedDocumentCounts: KnowledgeSourceSitemapIndexedDocumentCounts;
  /** Label types associated with this knowledge source, used to scope AI search results to specific topics. */
  labelTypes: Array<LabelType>;
  /** The current indexing status of this knowledge source: pending (queued), indexed (ready for AI), or failed. */
  status: IndexingStatus;
  type: KnowledgeSourceType;
  updatedAt: DateTime;
  updatedBy: InternalActor;
  url: Scalars['String']['output'];
};

/** Counts of a sitemap's crawled URLs, broken down by indexing status. */
export type KnowledgeSourceSitemapIndexedDocumentCounts = {
  /** URLs that failed to index. */
  failed: Scalars['Int']['output'];
  /** URLs successfully indexed and available to the AI. */
  indexed: Scalars['Int']['output'];
  /** URLs queued for indexing but not yet indexed. */
  pending: Scalars['Int']['output'];
  /** Total number of URLs crawled from the sitemap, regardless of status. */
  total: Scalars['Int']['output'];
};

export type KnowledgeSourceType =
  /** A knowledge source backed by a sitemap XML file. Plain crawls and indexes every URL listed in the sitemap. */
  | 'SITEMAP'
  /** A knowledge source backed by a single URL. Plain fetches and indexes the content of that page. */
  | 'URL';

