export type RoleChangeCost = {
  addingSeatType: BillingSeatType;
  /**
   * The total price delta for the remainder of the current billing period (i.e. prorated).
   * Could be negative (e.g. swapping member for viewer).
   */
  adjustedPrice: Price;
  /**
   * Total amount that will be invoiced immediately for the role change.
   * If this is negative, we would credit the amount to your account.
   */
  dueNowPrice: Price;
  /**
   * The total price delta for the entire subscription billing period (i.e. non-prorated).
   * Could be negative (e.g. swapping member for viewer).
   */
  fullPrice: Price;
  intervalCount: Scalars['Int']['output'];
  intervalUnit: BillingIntervalUnit;
  /** The number of seats. */
  quantity: Scalars['Int']['output'];
  removingSeatType?: Maybe<BillingSeatType>;
  /** Deprecated. Use fullPrice instead. */
  totalPrice: Price;
};

export type RoleConnection = {
  edges: Array<RoleEdge>;
  pageInfo: PageInfo;
};

export type RoleEdge = {
  cursor: Scalars['String']['output'];
  node: Role;
};

export type RoleFilter = {
  version?: InputMaybe<Scalars['Int']['input']>;
};

/** Stable identifiers for the built-in workspace roles. */
export type RoleKey =
  | 'ADMIN'
  /** Represents no role — the user exists in the workspace but has no permissions. */
  | 'NONE'
  | 'OWNER'
  | 'SUPPORT'
  | 'VIEWER';

export type RoleScope = {
  /** Whether users see all threads, only threads matching specific values, or all threads except those matching specific values. */
  accessMode: RoleScopeAccessMode;
  /** The dimension on which thread visibility is filtered (e.g. label, tier, channel). */
  primitiveType: ThreadScopePrimitiveType;
  /** IDs of the values included/excluded (empty for VIEW_ANY). */
  values: Array<Scalars['ID']['output']>;
};

export type RoleScopeAccessMode =
  /** See all resources except those with these values */
  | 'VIEW_ALL_EXCEPT'
  /** See all resources regardless of this primitive (default) */
  | 'VIEW_ANY'
  /** See only resources with these specific values */
  | 'VIEW_ONLY';

export type RoleScopeDefinition = {
  resource: RoleScopeResourceType;
  scopes: Array<RoleScope>;
};

/** The type of resource that a role scope applies to. Currently only threads are supported. */
export type RoleScopeResourceType =
  | 'THREAD';

