export type ServiceAuthorization = {
  /** Timestamp when the service authorization moved to CONNECTED status for the first time. */
  connectedAt: DateTime;
  connectedBy: InternalActor;
  createdAt: DateTime;
  createdBy: InternalActor;
  id: Scalars['ID']['output'];
  /**
   * Whether this service authorization uses the import runner system for syncing data into Plain.
   * When true, data is synced via Plain's import runner pipeline. When false, data is synced
   * via the legacy Nango-managed sync pipeline.
   */
  isImportRunnerIntegration: Scalars['Boolean']['output'];
  /** The third-party service this authorization connects to, including its name and integration key. */
  serviceIntegration: ServiceIntegration;
  status: ServiceAuthorizationStatus;
  updatedAt: DateTime;
  updatedBy: InternalActor;
};

export type ServiceAuthorizationConnection = {
  edges: Array<ServiceAuthorizationEdge>;
  pageInfo: PageInfo;
};

export type ServiceAuthorizationConnectionDetails = {
  /** HMAC-SHA256 digest that must be included in the OAuth authorization URL to verify the callback belongs to this workspace. */
  hmacDigest: Scalars['String']['output'];
  /** The ID of the pending service authorization. Pass this to completeServiceAuthorization after the OAuth callback. */
  serviceAuthorizationId: Scalars['ID']['output'];
  /** One of: zendesk, salesforce, freshdesk, helpscout-mailbox, hubspot, jira, shortcut, rootly, incidentio, github-app-oauth, attio. */
  serviceIntegrationKey: Scalars['String']['output'];
};

export type ServiceAuthorizationEdge = {
  cursor: Scalars['String']['output'];
  node: ServiceAuthorization;
};

/**
 * The status of the service authorization. The status transitions are:
 * PENDING_AUTH → COMPLETED_AUTH → CONNECTED ↔ REINSTALL_REQUIRED
 *
 * Once connected, the status may revert to REINSTALL_REQUIRED if the integration is revoked
 * in the third-party service; re-running the authorization flow will restore it to CONNECTED.
 */
export type ServiceAuthorizationStatus =
  /**
   * User has completed the service authorization, but the service is not yet ready for use.
   * This happens when the service requires additional configuration (e.g. creating webhooks
   * in the service).
   * This is a transient state that typically lasts for a few seconds. Plain will automatically
   * attempt to configure the service, and transition to CONNECTED or REINSTALL_REQUIRED.
   */
  | 'COMPLETED_AUTH'
  /** Service authorization is connected and ready for use. */
  | 'CONNECTED'
  /** Service authorization was requested, but the user has not yet completed the authorization. */
  | 'PENDING_AUTH'
  /**
   * Service authorization was revoked, this typically happen when the Plain integration is removed
   * from the service. Plain keeps the service authorization to allow for reconnection without
   * losing the service's configuration.
   */
  | 'REINSTALL_REQUIRED';

export type ServiceAuthorizationsFilter = {
  /** One of: zendesk, salesforce, freshdesk, helpscout-mailbox, hubspot, jira, shortcut, rootly, incidentio, github-app-oauth, attio. */
  serviceIntegrationKey?: InputMaybe<Scalars['String']['input']>;
};

export type ServiceIntegration = {
  key: Scalars['String']['output'];
  name: Scalars['String']['output'];
};

/** A service level agreement (SLA) attached to a tier. Every thread belonging to the tier inherits the SLA and is tracked against its time target. */
export type ServiceLevelAgreement = {
  /** The actions to take when the SLA is about to breach and when it breaches. */
  breachActions: Array<BreachAction>;
  /** The business hours schedules this SLA is tracked against. Empty if the SLA is tracked 24/7. */
  businessHoursSchedules: Array<BusinessHoursSchedule>;
  createdAt: DateTime;
  createdBy: InternalActor;
  id: Scalars['ID']['output'];
  /** This SLA can only be applied to a thread if it has one of these label types. */
  threadLabelTypeIdFilter?: Maybe<ServiceLevelAgreementThreadLabelTypeIdFilter>;
  /** This SLA can only be applied to a thread if it has one of these priority values. */
  threadPriorityFilter: Array<Scalars['Int']['output']>;
  updatedAt: DateTime;
  updatedBy: InternalActor;
  /**
   * If true, the SLA will only be tracked during your workspace's business hours. If false, the SLA will tracked 24/7. Deprecated — use businessHoursSchedules instead.
   * @deprecated Use businessHoursSchedules to see which business hours are linked to this SLA.
   */
  useBusinessHoursOnly: Scalars['Boolean']['output'];
};

export type ServiceLevelAgreementFilter = {
  statuses?: InputMaybe<Array<ServiceLevelAgreementStatus>>;
  types?: InputMaybe<Array<ServiceLevelAgreementType>>;
  updatedAt?: InputMaybe<DatetimeFilter>;
};

export type ServiceLevelAgreementInput = {
  /** The actions to take when the SLA is about to breach and when it breaches. */
  breachActions: Array<BreachActionInput>;
  /** The business hours schedules to track this SLA against. Replaces useBusinessHoursOnly. Pass an empty array for the SLA to be tracked 24/7. */
  businessHoursScheduleIds?: InputMaybe<Array<Scalars['ID']['input']>>;
  /** Set this to configure a first-resolution-time SLA. The clock starts when the thread arrives and the SLA is met when the thread is first marked Done. */
  firstResolutionTimeMinutes?: InputMaybe<Scalars['Int']['input']>;
  /** Set this to configure the first response time SLA. */
  firstResponseTimeMinutes?: InputMaybe<Scalars['Int']['input']>;
  /** Set this to configure an SLA for next responses. */
  nextResponseTimeMinutes?: InputMaybe<Scalars['Int']['input']>;
  /** The thread status details that pause the resolution-time clock. Only valid with firstResolutionTimeMinutes or totalResolutionTimeMinutes. Defaults to [WAITING_FOR_CUSTOMER]. Pass an empty array to keep the clock running. */
  pauseOnStatusDetailTypes?: InputMaybe<Array<ServiceLevelAgreementPauseStatusDetailType>>;
  /** This SLA can only be applied to a thread if it has one or all of these label types. If not provided, the filter is not applied. */
  threadLabelTypeIdFilter?: InputMaybe<ServiceLevelAgreementThreadLabelTypeIdFilterInput>;
  /** This SLA can only be applied to a thread if it has one of these priority values. If not provided, it defaults to all priorities (0, 1, 2 and 3). */
  threadPriorityFilter?: InputMaybe<Array<Scalars['Int']['input']>>;
  /** Set this to configure a total-resolution-time SLA. The clock starts when the thread arrives and continues across reopenings until the thread is marked Done. */
  totalResolutionTimeMinutes?: InputMaybe<Scalars['Int']['input']>;
  /**
   * If true, the SLA will only be tracked during your workspace's business hours. If false, the SLA will be tracked 24/7. Deprecated — use businessHoursScheduleIds instead.
   * @deprecated Use businessHoursScheduleIds to specify which business hours are linked to this SLA.
   */
  useBusinessHoursOnly?: InputMaybe<Scalars['Boolean']['input']>;
};

/** Thread status details a resolution-time SLA can pause on. */
export type ServiceLevelAgreementPauseStatusDetailType =
  | 'IN_PROGRESS'
  | 'THREAD_DISCUSSION_RESOLVED'
  | 'THREAD_LINK_UPDATED'
  | 'WAITING_FOR_CUSTOMER'
  | 'WAITING_FOR_DURATION'
  | 'WAITING_INDEFINITELY';

export type ServiceLevelAgreementPauseStatusDetailTypeArrayInput = {
  value: Array<ServiceLevelAgreementPauseStatusDetailType>;
};

/** Narrows the SLA policy list. Omit a field to leave that dimension unconstrained. */
export type ServiceLevelAgreementPoliciesFilter = {
  /** Narrows to policies whose name contains this, matched case-insensitively and unanchored. Searched in the database rather than on the page, so it finds policies a client has not loaded. */
  searchQuery?: InputMaybe<Scalars['String']['input']>;
  /** Narrows to policies holding a target of at least one of these types. A policy with no target of any given type is excluded. */
  serviceLevelAgreementTypes?: InputMaybe<Array<ServiceLevelAgreementType>>;
};

/** A named group of SLA targets that a workflow or a user applies to a thread. Unlike tier SLAs, a policy's targets are selected by type alone, so a policy holds at most one target per type. */
export type ServiceLevelAgreementPolicy = {
  createdAt: DateTime;
  createdBy: InternalActor;
  description?: Maybe<Scalars['String']['output']>;
  id: Scalars['ID']['output'];
  name: Scalars['String']['output'];
  /** The SLA targets this policy applies. At most one per type. */
  targets: Array<ServiceLevelAgreementPolicyTarget>;
  updatedAt: DateTime;
  updatedBy: InternalActor;
};

export type ServiceLevelAgreementPolicyConnection = {
  edges: Array<ServiceLevelAgreementPolicyEdge>;
  pageInfo: PageInfo;
};

export type ServiceLevelAgreementPolicyEdge = {
  cursor: Scalars['String']['output'];
  node: ServiceLevelAgreementPolicy;
};

/** An SLA policy as it was when a timeline entry was written. Policies can be renamed or deleted afterwards, so this is a snapshot rather than a link. */
export type ServiceLevelAgreementPolicyRef = {
  id: Scalars['ID']['output'];
  name: Scalars['String']['output'];
};

/** One time-to-target promise inside an SLA policy. A policy holds at most one target of each type. */
export type ServiceLevelAgreementPolicyTarget = {
  /** The business hours schedules this SLA target is tracked against. Empty if tracked 24/7. */
  businessHoursSchedules: Array<BusinessHoursSchedule>;
  createdAt: DateTime;
  createdBy: InternalActor;
  id: Scalars['ID']['output'];
  /** This target breaches if the SLA is not met within this many minutes. */
  minutes: Scalars['Int']['output'];
  /** The thread status details that pause this resolution-time clock. Empty means the clock never pauses. Null for first-response and next-response targets. */
  pauseOnStatusDetailTypes?: Maybe<Array<ServiceLevelAgreementPauseStatusDetailType>>;
  type: ServiceLevelAgreementType;
  updatedAt: DateTime;
  updatedBy: InternalActor;
  warnBefore?: Maybe<ServiceLevelAgreementWarnBefore>;
};

export type ServiceLevelAgreementPolicyTargetInput = {
  /** The business hours schedules to track this target against. Leave it out or pass an empty array for the target to be tracked 24/7; leave it out when updating and the target keeps the schedules it already has. */
  businessHoursScheduleIds?: InputMaybe<Array<Scalars['ID']['input']>>;
  /** This target will breach if the SLA is not met within this many minutes. */
  minutes: Scalars['Int']['input'];
  /** The thread status details that pause the resolution-time clock. Only valid when type is FIRST_RESOLUTION_TIME or TOTAL_RESOLUTION_TIME. Defaults to [WAITING_FOR_CUSTOMER]. Pass an empty array to keep the clock running. */
  pauseOnStatusDetailTypes?: InputMaybe<Array<ServiceLevelAgreementPauseStatusDetailType>>;
  /** The type of target. A policy can hold at most one target of each type. */
  type: ServiceLevelAgreementType;
  warnBefore: ServiceLevelAgreementWarnBeforeInput;
};

/** The lifecycle status of an SLA tracker for a given thread. */
export type ServiceLevelAgreementStatus =
  /** The SLA was met within the deadline. */
  | 'ACHIEVED'
  /** The SLA deadline passed without being met, and the tracker was subsequently completed. */
  | 'BREACHED'
  /** The SLA deadline has passed and the SLA has not yet been met. */
  | 'BREACHING'
  /** The SLA was cancelled for this thread, e.g. because the thread's tier or priority changed after creation. */
  | 'CANCELLED'
  /** The SLA deadline is approaching; a breach is imminent based on the configured `beforeBreachMinutes` action. */
  | 'IMMINENT_BREACH'
  /** The SLA is active and the deadline has not yet been reached. */
  | 'PENDING';

export type ServiceLevelAgreementStatusDetail = ServiceLevelAgreementStatusDetailAchieved | ServiceLevelAgreementStatusDetailBreached | ServiceLevelAgreementStatusDetailBreaching | ServiceLevelAgreementStatusDetailCancelled | ServiceLevelAgreementStatusDetailImminentBreach | ServiceLevelAgreementStatusDetailPending;

export type ServiceLevelAgreementStatusDetailAchieved = {
  /** The time when this SLA was achieved. */
  achievedAt: DateTime;
};

export type ServiceLevelAgreementStatusDetailBreached = {
  /** The time when this SLA breached. */
  breachedAt: DateTime;
  /** The time when we completed this breached SLA. */
  completedAt: DateTime;
};

export type ServiceLevelAgreementStatusDetailBreaching = {
  /** The time when this SLA breached. */
  breachedAt: DateTime;
};

export type ServiceLevelAgreementStatusDetailCancelled = {
  /** The time when this SLA was cancelled. */
  cancelledAt: DateTime;
};

export type ServiceLevelAgreementStatusDetailImminentBreach = {
  /** The time when this SLA will breach. */
  breachingAt: DateTime;
  /** When set, the SLA clock is paused at this instant. Present for resolution-time SLAs while the thread is in a pause status. */
  pausedAt?: Maybe<DateTime>;
  /** Business minutes remaining when the SLA clock was paused. Null when the SLA is not paused. Never negative. */
  remainingMinutesAtPause?: Maybe<Scalars['Int']['output']>;
};

export type ServiceLevelAgreementStatusDetailPending = {
  /** The time when this SLA will breach. */
  breachingAt: DateTime;
  /** When set, the SLA clock is paused at this instant. Present for resolution-time SLAs while the thread is in a pause status. */
  pausedAt?: Maybe<DateTime>;
  /** Business minutes remaining when the SLA clock was paused. Null when the SLA is not paused. Never negative. */
  remainingMinutesAtPause?: Maybe<Scalars['Int']['output']>;
};

/** A snapshot of the current SLA tracking status for a thread, broken down by SLA type. */
export type ServiceLevelAgreementStatusSummary = {
  /** Current tracking status for the first-resolution-time SLA, if one applies to this thread. */
  firstResolutionTime?: Maybe<ServiceLevelAgreementStatusDetail>;
  /** Current tracking status for the first-response-time SLA, if one applies to this thread. */
  firstResponseTime?: Maybe<ServiceLevelAgreementStatusDetail>;
  /** Current tracking status for the next-response-time SLA, if one applies to this thread. */
  nextResponseTime?: Maybe<ServiceLevelAgreementStatusDetail>;
  /** Current tracking status for the total-resolution-time SLA, if one applies to this thread. */
  totalResolutionTime?: Maybe<ServiceLevelAgreementStatusDetail>;
};

/** A timeline entry recording a change in the SLA tracking status for a thread. */
export type ServiceLevelAgreementStatusTransitionedEntry = {
  /** The SLA status after the transition. */
  nextStatus: ServiceLevelAgreementStatus;
  /** The SLA status before the transition. */
  previousStatus: ServiceLevelAgreementStatus;
  serviceLevelAgreement?: Maybe<ServiceLevelAgreement>;
};

/** Restricts which threads an SLA applies to based on their label types. */
export type ServiceLevelAgreementThreadLabelTypeIdFilter = {
  /** The label type IDs that the thread needs to have in order for the SLA to be applied. Based on the 'requireAll' field. */
  labelTypeIds: Array<Scalars['ID']['output']>;
  /** If true, the SLA will only be applied to threads that have all of the provided label types. If false, the SLA will be applied to threads that have any of the provided label types. */
  requireAll: Scalars['Boolean']['output'];
};

export type ServiceLevelAgreementThreadLabelTypeIdFilterInput = {
  /** The label type IDs that the thread needs to have in order for the SLA to be applied. Based on the 'requireAll' field. */
  labelTypeIds: Array<Scalars['ID']['input']>;
  /** If true, the SLA will only be applied to threads that have all of the provided label types. If false, the SLA will be applied to threads that have any of the provided label types. */
  requireAll: Scalars['Boolean']['input'];
};

export type ServiceLevelAgreementType =
  | 'FIRST_RESOLUTION_TIME'
  | 'FIRST_RESPONSE_TIME'
  | 'NEXT_RESPONSE_TIME'
  | 'TOTAL_RESOLUTION_TIME';

/** How far ahead of an SLA target's deadline the thread is treated as close to breaching. */
export type ServiceLevelAgreementWarnBefore = {
  /** How many minutes before the deadline the SLA is treated as close to breaching. */
  minutes: Scalars['Int']['output'];
};

export type ServiceLevelAgreementWarnBeforeInput = {
  /** How many minutes before the deadline the SLA is treated as close to breaching. Must be strictly less than the target. */
  minutes: Scalars['Int']['input'];
};

