/** A tool available to Sidekick in this workspace. */
export type SidekickAvailableTool = {
  /** The workspace's effective approval mode (override merged over factory default): `not_required`, `approval_required`, or `disabled`. Disabled tools are rejected at runtime even if granted; `approval_required` tools granted to a workflow step run without a human approval. */
  approvalMode: Scalars['String']['output'];
  /** Op args a workflow grant can pin at build time (e.g. the Slack channel on `chat.postMessage`). Empty for most tools. */
  configurableArgs: Array<SidekickToolConfigurableArg>;
  /** One-line description of what the tool does. */
  description: Scalars['String']['output'];
  /** Human label for the tool. */
  displayName: Scalars['String']['output'];
  /** The operation identifier, e.g. `thread.addLabels` or `chat.postMessage`. */
  op: Scalars['String']['output'];
  /** Whether the op observes or mutates: `read`, `write`, or `destructive`. Reads are granted automatically to a restricted Sidekick session for any service it has at least one granted tool on, so pickers should offer writes as the selectable actions. */
  risk: Scalars['String']['output'];
  /** The service the tool belongs to, e.g. `plain`, `slack`. */
  service: Scalars['String']['output'];
};

export type SidekickConnectRequestStatus =
  | 'CONNECTED'
  | 'PENDING';

export type SidekickConnectRequestTool = {
  /** True once the workspace has authorized this integration. */
  isConnected: Scalars['Boolean']['output'];
  name: Scalars['String']['output'];
  /** Sidekick integration slug, e.g. `linear`. Matches the settings deep-link segment. */
  slug: Scalars['String']['output'];
};

/** The monthly allowance credit bucket. */
export type SidekickCreditAllowanceBalance = {
  /** Credits granted for the current period. Null when the subscription line item is unavailable — grant/used can't be determined, but remaining still holds. */
  grant?: Maybe<Scalars['Int']['output']>;
  /** The low-balance warning threshold, if one is configured. */
  lowBalanceThreshold?: Maybe<Scalars['Int']['output']>;
  /** End of the current billing period in ISO 8601, when the allowance resets. Null when unavailable. */
  periodEndsAt?: Maybe<Scalars['String']['output']>;
  /** Credits still available in the monthly allowance. */
  remaining: Scalars['Int']['output'];
  /** Credits consumed this period, best-effort as max(0, grant - remaining). Null when grant is unavailable. */
  used?: Maybe<Scalars['Int']['output']>;
};

/** The workspace's current Sidekick (Plain) credit balance. */
export type SidekickCreditBalance = {
  /** The recurring monthly allowance bucket. Null when the workspace has no allowance credit product attached (e.g. a plan without credits, or pre-onboarding). */
  allowance?: Maybe<SidekickCreditAllowanceBalance>;
  /** Whether metered credits apply. When UNMETERED (e.g. a trial), Sidekick is free and there is no balance — both buckets are null. */
  status: SidekickCreditBalanceStatus;
  /** The purchased top-up bucket, consumed after the monthly allowance is exhausted. Null when the workspace has no top-up balance. */
  topup?: Maybe<SidekickCreditTopupBalance>;
};

/** Whether metered Sidekick credits apply to the workspace. */
export type SidekickCreditBalanceStatus =
  /** The workspace has a metered credit account; `allowance`/`topup` reflect real balances. */
  | 'TRACKED'
  /** Sidekick is free and unmetered for this workspace — e.g. during a trial, or on a plan without Sidekick credits — so there is no balance to count down and `allowance`/`topup` are null. */
  | 'UNMETERED';

/** The purchased top-up credit bucket. */
export type SidekickCreditTopupBalance = {
  /** Credits still available from purchased top-ups. */
  remaining: Scalars['Int']['output'];
};

/** Credit usage broken down by UTC day. */
export type SidekickCreditUsageByDay = {
  /** One entry per day in the range that had usage, ordered by day ascending. */
  days: Array<SidekickCreditUsageDay>;
};

export type SidekickCreditUsageByDayInput = {
  /** Start of the range, inclusive. ISO 8601 format (e.g. 2026-06-01T00:00:00Z). */
  from: Scalars['String']['input'];
  /** End of the range, exclusive. ISO 8601 format (e.g. 2026-07-01T00:00:00Z). */
  to: Scalars['String']['input'];
};

/** Credit usage for a single UTC day. */
export type SidekickCreditUsageDay = {
  /** Credits charged across the billable items that resolved on this day. */
  credits: Scalars['Int']['output'];
  /** Start of the UTC day this usage falls in. */
  day: DateTime;
  /** Number of billable items that resolved on this day, not only Sidekick sessions. */
  sessionCount: Scalars['Int']['output'];
};

