/** API-key auth config for a custom MCP server. Providing this on create registers the server as API-key rather than OAuth. */
export type SidekickMcpApiKeyAuthInput = {
  /** The auth attachments (name + placement) the API key(s) are sent in. At least one required. The secret values are entered client-side and vaulted in Nango, never sent here. */
  params: Array<SidekickMcpAuthParamInput>;
};

/** One configured API-key auth attachment: the non-secret name and where it is attached. The secret value is never exposed. */
export type SidekickMcpAuthParam = {
  name: Scalars['String']['output'];
  placement: SidekickMcpAuthParamPlacement;
};

/** One API-key auth attachment to configure on create: the non-secret name plus where the secret is attached. */
export type SidekickMcpAuthParamInput = {
  /** The header or query-param name the secret is sent in, e.g. Authorization. Header names must be valid header-name tokens. */
  name: Scalars['String']['input'];
  placement: SidekickMcpAuthParamPlacement;
};

/** Where an API-key secret is attached on each outbound request: an HTTP header or a URL query param. */
export type SidekickMcpAuthParamPlacement =
  | 'HEADER'
  | 'QUERY';

/** An icon a custom MCP server declares in its serverInfo, captured at discovery. src is an https or data: URI. */
export type SidekickMcpIcon = {
  mimeType?: Maybe<Scalars['String']['output']>;
  sizes: Array<Scalars['String']['output']>;
  src: Scalars['String']['output'];
};

/** A customer-owned MCP server registered for Sidekick. Sidekick reaches it only via the trusted proxy (the customer credential never enters the sandbox). */
export type SidekickMcpServer = {
  /** For API-key servers, the auth attachments (name + placement) the key(s) are sent in, e.g. Authorization as a header. Empty for OAuth servers. The secret values are never exposed. */
  authParams: Array<SidekickMcpAuthParam>;
  authType: SidekickMcpServerAuthType;
  /** The server's own icons, captured from its serverInfo at discovery. Empty if it declares none. */
  icons: Array<SidekickMcpIcon>;
  id: Scalars['ID']['output'];
  /** False until completeSidekickMcpServerConnection succeeds. Sidekick ignores a server that is not connected. */
  isConnected: Scalars['Boolean']['output'];
  name: Scalars['String']['output'];
  operatingInstructions?: Maybe<Scalars['String']['output']>;
  /** Stable, workspace-unique identifier derived from the name; used as the mcp__<slug> service key. */
  slug: Scalars['String']['output'];
  /** Served from the cached discovery snapshot, never a live MCP call. */
  tools: Array<SidekickMcpTool>;
  url: Scalars['String']['output'];
};

/** How a custom MCP server authenticates: brokered OAuth, or a static API key attached in configurable headers and/or URL query params. */
export type SidekickMcpServerAuthType =
  | 'API_KEY'
  | 'OAUTH';

/** One tool discovered on a custom MCP server, served from the cached discovery snapshot. */
export type SidekickMcpTool = {
  description: Scalars['String']['output'];
  displayName: Scalars['String']['output'];
  name: Scalars['String']['output'];
};

