/**
 * A rule defining which Slack channels the Plain bot automatically joins, plus
 * optional default channel options applied when a channel is connected via
 * this rule.
 */
export type SlackAutoJoinRule = {
  /** Plain joins any new Slack channel whose name starts with this string. Empty string means no prefix filter. */
  channelNamePrefix: Scalars['String']['output'];
  /** Plain joins any new Slack channel whose name ends with this string. Empty string means no suffix filter. */
  channelNameSuffix: Scalars['String']['output'];
  /** Null means the channel mode is detected automatically (current behaviour). */
  defaultChannelMode?: Maybe<SlackAutoJoinRuleChannelMode>;
  /** Null means the team default ingestion mode applies. */
  defaultIngestionMode?: Maybe<SlackAutoJoinRuleIngestionMode>;
  /**
   * Null for legacy rules read from the prefix/suffix settings that have not
   * yet been saved through `setSlackAutoJoinRules`.
   */
  id?: Maybe<Scalars['ID']['output']>;
  /** The workspace Slack channel integration this rule belongs to. */
  integrationId: Scalars['ID']['output'];
};

/** The default channel mode an auto-join rule applies to newly joined channels. */
export type SlackAutoJoinRuleChannelMode =
  /** Connect the channel as a customer channel. */
  | 'CUSTOMER'
  /** Connect the channel in a disabled state. */
  | 'DISABLED'
  /** Connect the channel as an internal discussion channel. */
  | 'DISCUSSION';

/**
 * The default thread-creation (ingestion) configuration an auto-join rule
 * applies to channels it connects. `manual` is set only when `type` is
 * `MANUAL`; it is null for other modes.
 */
