export type ThreadLinkGroup = {
  /**
   * Breakdown of linked thread counts by account, including threads with no account.
   * A thread is matched to its own account and to any EMAIL_DOMAIN account its customer
   * is a member of. The thread will be counted once per account, so total counts for
   * account metrics may sum to more than the group's total thread links.
   */
  accountMetrics: ThreadLinkGroupAccountMetrics;
  /** Breakdown of linked thread counts by company, including threads with no company. */
  companyMetrics: ThreadLinkGroupCompanyMetrics;
  /**
   * The current rank of the thread link group considering groups
   * which match the non-ID input filters.
   */
  currentViewRank: Scalars['Int']['output'];
  /**
   * The default rank of the thread link group which takes into account
   * only active groups. This rank is not affected by input filters.
   */
  defaultViewRank?: Maybe<Scalars['Int']['output']>;
  id: Scalars['ID']['output'];
  /**
   * Breakdown of linked thread counts by tenant, including threads with no tenant.
   * A thread is matched to its own tenant and to any EMAIL_DOMAIN tenant its customer
   * is a member of. The thread will be counted once per tenant, so total counts for
   * tenant metrics may sum to more than the group's total thread links.
   */
  tenantMetrics: ThreadLinkGroupTenantMetrics;
  /** The individual thread link records that belong to this group. */
  threadLinks: ThreadLinkConnection;
  /** All threads that are linked to this group's external entity. */
  threads: ThreadConnection;
  /** Breakdown of linked thread counts by tier, including threads with no tier. */
  tierMetrics: ThreadLinkGroupTierMetrics;
};


