export type WebhookDeliveryAttemptRejectedResult = {
  rejectedMessage: Scalars['String']['output'];
  status: WebhookDeliveryAttemptResultStatus;
};

export type WebhookDeliveryAttemptResult = WebhookDeliveryAttemptErrorResult | WebhookDeliveryAttemptFailedResult | WebhookDeliveryAttemptRejectedResult | WebhookDeliveryAttemptSchemaValidationFailedResult | WebhookDeliveryAttemptSuccessfulResult;

export type WebhookDeliveryAttemptResultStatus =
  /** A network-level error occurred before a response was received (e.g. connection timeout or DNS failure). */
  | 'ERROR'
  /** The endpoint returned a non-2xx HTTP status code (4xx or 5xx). */
  | 'FAILED_RESPONSE'
  /** Plain rejected the delivery before it was attempted, for example because the target was disabled. */
  | 'REJECTED'
  /** The event payload failed schema validation against the target's pinned webhook version. */
  | 'SCHEMA_VALIDATION_FAILED'
  /** Plain received a 2xx HTTP response from the endpoint. */
  | 'SUCCESSFUL_RESPONSE';

export type WebhookDeliveryAttemptSchemaValidationFailedResult = {
  errorMessage: Scalars['String']['output'];
  status: WebhookDeliveryAttemptResultStatus;
};

export type WebhookDeliveryAttemptSuccessfulResult = {
  httpStatusCode: Scalars['Int']['output'];
  status: WebhookDeliveryAttemptResultStatus;
};

