export type WeekDay =
  | 'FRIDAY'
  | 'MONDAY'
  | 'SATURDAY'
  | 'SUNDAY'
  | 'THURSDAY'
  | 'TUESDAY'
  | 'WEDNESDAY';

/**
 * Short-lived WorkOS admin portal URLs and an embeddable widget token for configuring SSO, directory sync, and domain verification.
 * All URLs and the widget token are generated on demand and should be used immediately; do not cache or store them.
 */
export type WorkOsConfiguration = {
  /** URL to configure directory sync settings in the WorkOS admin portal. */
  directorySyncUrl: Scalars['String']['output'];
  /** URL to configure domain verification settings in the WorkOS admin portal. When the workspace is hub-linked, this points at the hub organization that holds the domain policy. */
  domainVerificationUrl: Scalars['String']['output'];
  /** URL to configure SSO settings in the WorkOS admin portal. */
  ssoUrl: Scalars['String']['output'];
  /** A short-lived token (valid for one hour) for rendering embedded WorkOS admin UI components directly in your own interface, as an alternative to redirecting users to the portal URLs. */
  widgetToken: Scalars['String']['output'];
};

export type Workflow = {
  createdAt: DateTime;
  createdBy: InternalActor;
  id: Scalars['ID']['output'];
  /**
   * When this workflow was most recently triggered, or null if it never has been. Dates the
   * trigger rather than the outcome, so a queued or failed run sets it as a successful one does.
   */
  lastTriggeredAt?: Maybe<DateTime>;
  name: Scalars['String']['output'];
  /**
   * 1-based dispatch priority among published event workflows with a start step, derived from
   * `position`, so `moveWorkflow` changes it. A lower number is always considered first, though
   * only the workflows listening for the arriving event run. 0 for anything outside that set.
   */
  order: Scalars['Int']['output'];
  /**
   * Opaque sort key. Compare lexicographically to order workflows within a workspace — the
   * connection is already returned in this order. Sorting locally cannot disagree with the server:
   * the encoding is ASCII-only (`0-9A-Za-z`), so JavaScript's `<` matches the database's byte
   * ordering. Do not construct, parse or persist it: the encoding may change. To reorder, use
   * `moveWorkflow`, which takes IDs.
   */
  position: Scalars['String']['output'];
  /** Timestamp when the workflow was last published. Null means the workflow is an inactive draft. */
  publishedAt?: Maybe<DateTime>;
  /**
   * Entities this workflow's steps reference, deduplicated across steps. Presence means a step
   * carries the id; whether that step runs depends on the workflow being published and its
   * conditions matching.
   */
  references: WorkflowReferences;
  /** The gallery template this workflow was created from, if any. Provenance only: the template may since have changed or been retired, and the workflow diverges as soon as it is edited. */
  sourceTemplateId?: Maybe<Scalars['ID']['output']>;
  /** The ID of the first step to execute, or null if the workflow has no steps. This cannot be cleared to null on a published workflow (`Cannot clear startStepId on a published workflow`); to restructure a published workflow's steps, unpublish it first (`updateWorkflow` with `isPublished: false`), restructure, then republish. */
  startStepId?: Maybe<Scalars['ID']['output']>;
  /** The steps in this workflow. */
  steps: Array<WorkflowStep>;
  /**
   * JSON-encoded trigger configuration, shaped as `{ "type": <triggerType>, ... }`. Valid types and their required fields:
   * - `manual` — no extra fields; the workflow runs only via the `triggerWorkflow` mutation or a UI button.
   * - `events` — `events: string[]` (at least one); runs on the listed domain events, e.g. `thread.thread_created`, `thread.message_added`, `thread.thread_field_updated`, `thread.thread_labels_changed`, `thread.thread_status_transitioned`, `thread.thread_discussion_created`, `thread.thread_discussion_message_created`, `thread.thread_discussion_resolved` (Slack and email discussions only; AI agent replies do not fire the message event). `thread.service_level_agreement_status_transitioned` fires on a status change of any SLA type; `thread.first_response_time_service_level_agreement_status_transitioned`, `thread.next_response_time_service_level_agreement_status_transitioned`, `thread.first_resolution_time_service_level_agreement_status_transitioned` and `thread.total_resolution_time_service_level_agreement_status_transitioned` fire only when an SLA of that type changes status. `slack.reaction_added` fires when any Slack emoji is added to a message already on a thread, including a reply; pair it with a `slack_emoji_equals` condition to match one emoji.
   * - `schedule` — `cron: string`; runs on a recurring cron schedule evaluated in UTC.
   * Examples: `{"type":"events","events":["thread.thread_field_updated"]}`, `{"type":"events","events":["thread.total_resolution_time_service_level_agreement_status_transitioned"]}`, `{"type":"events","events":["slack.reaction_added"]}`.
   */
  trigger: Scalars['String']['output'];
  updatedAt: DateTime;
  updatedBy: InternalActor;
};

/** Which blocks a workflow of a given trigger type may contain. Used to drive the builder palette. */
export type WorkflowCapabilities = {
  /** Action step types this workflow is restricted to (e.g. `send_slack_notification`). An empty list means no restriction (all action types are allowed). */
  allowedActionTypes: Array<Scalars['String']['output']>;
  /** Whether condition steps are allowed. */
  hasConditionSupport: Scalars['Boolean']['output'];
  /** Whether the `ask_sidekick` (Sidekick action) block is available. */
  hasSidekickActionSupport: Scalars['Boolean']['output'];
  /** Whether wait steps are allowed. */
  hasWaitSupport: Scalars['Boolean']['output'];
};

/** A change to a workflow. Refetch `workflow(workflowId)` to re-render the current graph; `workflowUpdatedAt` is the workflow's `updatedAt` — a monotonic change token you can use to dedupe. It is null when the workflow was removed. */
export type WorkflowChange = {
  changeType: ChangeType;
  workflowId: Scalars['ID']['output'];
  workflowUpdatedAt?: Maybe<DateTime>;
};

export type WorkflowConnection = {
  edges: Array<WorkflowEdge>;
  pageInfo: PageInfo;
};

export type WorkflowEdge = {
  cursor: Scalars['String']['output'];
  node: Workflow;
};

export type WorkflowExecution = {
  /** When the execution reached a terminal state (SUCCESS, FAILED, or CANCELLED). */
  completedAt?: Maybe<DateTime>;
  /** The ID of the entity this execution was triggered for. */
  entityId?: Maybe<Scalars['ID']['output']>;
  /** The type of entity this execution was triggered for. */
  entityType?: Maybe<WorkflowExecutionEntityType>;
  /** Human-readable error message when `executionStatus` is FAILED. */
  errorMessage?: Maybe<Scalars['String']['output']>;
  /** How long the run took to execute, in milliseconds. Measured from when it began processing, so it excludes time spent queued. */
  executionDurationMs?: Maybe<Scalars['Int']['output']>;
  executionStatus: WorkflowExecutionStatus;
  id: Scalars['ID']['output'];
  /** The actor that manually triggered this execution, if it was manually triggered. */
  manuallyTriggeredBy?: Maybe<InternalActor>;
  /** When the execution began processing. While QUEUED, the time it was enqueued. */
  startedAt?: Maybe<DateTime>;
  /** The step executions for this workflow execution. */
  stepExecutions: Array<WorkflowStepExecution>;
  /** The event type that triggered this execution (e.g., thread.thread_created). */
  triggeredBy: Scalars['String']['output'];
  /** The workflow this execution belongs to. Null if the workflow has been deleted. */
  workflow?: Maybe<Workflow>;
  workflowId: Scalars['ID']['output'];
};

export type WorkflowExecutionByEntityFilter = {
  entityId: Scalars['ID']['input'];
  entityType: WorkflowExecutionEntityType;
  executionStatus?: InputMaybe<WorkflowExecutionStatus>;
  workflowId?: InputMaybe<Scalars['ID']['input']>;
};

export type WorkflowExecutionConnection = {
  edges: Array<WorkflowExecutionEdge>;
  pageInfo: PageInfo;
};

export type WorkflowExecutionEdge = {
  cursor: Scalars['String']['output'];
  node: WorkflowExecution;
};

export type WorkflowExecutionEntityType =
  | 'THREAD'
  | 'WORKSPACE';

/** The lifecycle state of a workflow execution. */
export type WorkflowExecutionStatus =
  /** Execution was cancelled before it could complete. */
  | 'CANCELLED'
  /** Execution stopped due to an error in a step. */
  | 'FAILED'
  /** Execution has been accepted and is waiting to be processed. */
  | 'QUEUED'
  /** Execution is actively running steps. */
  | 'RUNNING'
  /** All steps completed successfully. */
  | 'SUCCESS'
  /** Execution is paused at a WAIT step until the configured duration elapses. */
  | 'WAITING';

/** Optional narrowing for `workflowExecutionsForWorkspace`. Every field is independent; omit them all to list the whole workspace. */
export type WorkflowExecutionsFilter = {
  /**
   * Only executions that ran against this entity — a thread id for event and manual workflows, or the
   * workspace's own id for scheduled ones. Ids carry their type, so no entity type is needed.
   */
  entityId?: InputMaybe<Scalars['ID']['input']>;
  /** Only executions in this state. */
  executionStatus?: InputMaybe<WorkflowExecutionStatus>;
  /** Only executions of this workflow. */
  workflowId?: InputMaybe<Scalars['ID']['input']>;
};

export type WorkflowReferences = {
  /** SLA policies applied by a `set_service_level_agreement_policy` action. */
  serviceLevelAgreementPolicyIds: Array<Scalars['ID']['output']>;
};

/** Entities a workflow step can reference. Fields combine with AND; an empty list is not a filter. At most 100 ids per field. */
export type WorkflowReferencesFilter = {
  /** Workflows with a `set_service_level_agreement_policy` action applying one of these policies. A step that clears the policy matches nothing. */
  serviceLevelAgreementPolicyIds?: InputMaybe<Array<Scalars['ID']['input']>>;
};

