export type WorkflowTemplateStep = {
  id: Scalars['ID']['output'];
  name?: Maybe<Scalars['String']['output']>;
  /** JSON-encoded payload containing the action or condition configuration. See `WorkflowStep.payload` for the valid `type` values per step type and the note on non-portable, workspace-specific IDs. */
  payload: Scalars['String']['output'];
  positionX: Scalars['Float']['output'];
  positionY: Scalars['Float']['output'];
  /** Array of next step IDs, mirroring WorkflowStep.transitions. */
  transitions: Array<Maybe<Scalars['ID']['output']>>;
  type: WorkflowStepType;
};

/** A workflow a template installs. Deliberately mirrors the shape the workflow editor parses. */
export type WorkflowTemplateWorkflow = {
  name: Scalars['String']['output'];
  /** The ID of the first step to execute, or null if the workflow has no steps. */
  startStepId?: Maybe<Scalars['ID']['output']>;
  steps: Array<WorkflowTemplateStep>;
  /** JSON-encoded trigger configuration. */
  trigger: Scalars['String']['output'];
};

/** Controls how a workflow is triggered. */
export type WorkflowTriggerType =
  /** The workflow runs automatically in response to domain events (e.g. thread created, label added). */
  | 'EVENTS'
  /** The workflow runs only when explicitly triggered via the `triggerWorkflow` mutation or a UI button. */
  | 'MANUAL'
  /** The workflow runs on a recurring cron schedule (evaluated in UTC), with no thread. */
  | 'SCHEDULE';

export type WorkflowsFilter = {
  /** Only workflows created by one of these users or machine users. Workflows created by the system have no user to match and are never returned when this filter is set. An empty list is not a filter. */
  createdByUserIds?: InputMaybe<Array<Scalars['ID']['input']>>;
  /** Filter by published status. true returns only published workflows (publishedAt set), false returns only unpublished workflows (publishedAt null). */
  isPublished?: InputMaybe<Scalars['Boolean']['input']>;
  /** Only workflows holding a step that references at least one of the given entities. Drafts are included; combine with `isPublished` to narrow. */
  references?: InputMaybe<WorkflowReferencesFilter>;
  /** Only workflows whose `events` trigger listens for at least one of these event types, e.g. `thread.thread_created`. Workflows with a `manual` or `schedule` trigger are never returned when this filter is set. An empty list is not a filter. */
  triggerEvents?: InputMaybe<Array<Scalars['String']['input']>>;
  triggerTypes?: InputMaybe<Array<WorkflowTriggerType>>;
};

export type WorkflowsSort = {
  direction: SortDirection;
  field: WorkflowsSortField;
};

/** How to order the `workflows` connection. */
export type WorkflowsSortField =
  /** When the workflow was created. */
  | 'CREATED_AT'
  /** When the workflow was last triggered. Workflows that have never run sort as the earliest possible instant, so they lead ascending and trail descending. */
  | 'LAST_TRIGGERED_AT'
  /** The workflow's name, ordered under the database's default collation. */
  | 'NAME'
  /** The workspace's own ordering, the default. Ascending matches the order the list is drawn in. */
  | 'POSITION'
  /** When the workflow was published. Drafts have no such time and sort as the earliest possible instant, so they lead ascending and trail descending. */
  | 'PUBLISHED_AT'
  /**
   * When the workflow row itself was last changed. Editing steps one at a time does not move it —
   * only `bulkUpsertWorkflowSteps` touches the workflow alongside its steps.
   */
  | 'UPDATED_AT';

